#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;
constexpr int32_t MAX_DIM = 8;

template <typename T>
class KernelPermute {
public:
    __aicore__ inline KernelPermute() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength,
                                int64_t ndim,
                                GM_ADDR inputShape, GM_ADDR outputShape,
                                GM_ADDR inputStride, GM_ADDR outputStride,
                                GM_ADDR dims)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x, offset + formerLength);
            yGm.SetGlobalBuffer((__gm__ T *)y, offset + formerLength);
            this->blockOffset = offset;
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x, offset + tailLength);
            yGm.SetGlobalBuffer((__gm__ T *)y, offset + tailLength);
            this->blockOffset = offset;
        }

        this->tileLength = tileLength;
        this->ndim = ndim;

        // Read shape/stride/dims from GM
        auto shapeGm = (__gm__ int64_t *)inputShape;
        auto outShapeGm = (__gm__ int64_t *)outputShape;
        auto strideGm = (__gm__ int64_t *)inputStride;
        auto outStrideGm = (__gm__ int64_t *)outputStride;
        auto dimsGm = (__gm__ int64_t *)dims;

        for (int64_t i = 0; i < ndim && i < MAX_DIM; ++i) {
            this->inputShape[i] = shapeGm[i];
            this->outputShape[i] = outShapeGm[i];
            this->inputStride[i] = strideGm[i];
            this->outputStride[i] = outStrideGm[i];
            this->dims[i] = dimsGm[i];
        }

        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            CopyIn(tileNum - 1, alignedTailLen);
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, alignedTailLen);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        // For permute, we don't actually copy data here - we compute indices in Compute
        // But we need to allocate the buffer for the pipeline
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();

        int64_t outGlobalOffset = this->blockOffset + progress * this->tileLength;

        // For each element in the tile, compute the output index and map to input index
        for (int64_t i = 0; i < curTileLength; ++i) {
            int64_t outIdx = outGlobalOffset + i;

            // Convert output linear index to output coordinates
            int64_t outCoords[MAX_DIM];
            int64_t tmp = outIdx;
            for (int64_t d = this->ndim - 1; d >= 0; --d) {
                outCoords[d] = tmp % this->outputShape[d];
                tmp /= this->outputShape[d];
            }

            // Map output coordinates to input coordinates using dims
            int64_t inCoords[MAX_DIM];
            for (int64_t d = 0; d < this->ndim; ++d) {
                inCoords[this->dims[d]] = outCoords[d];
            }

            // Compute input linear index
            int64_t inIdx = 0;
            for (int64_t d = 0; d < this->ndim; ++d) {
                inIdx += inCoords[d] * this->inputStride[d];
            }

            // Copy element from input to output
            yLocal.SetValue(i, xGm.GetValue(inIdx));
        }

        outQueueY.EnQue<T>(yLocal);
        inQueueX.FreeTensor(xLocal);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
        int64_t globalOffset = this->blockOffset + progress * this->tileLength;

        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(yGm[globalOffset], yLocal, copyParams);
        outQueueY.FreeTensor(yLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
    AscendC::GlobalTensor<T> xGm;
    AscendC::GlobalTensor<T> yGm;
    int64_t blockLength;
    int64_t tileLength;
    int64_t blockOffset;
    int64_t ndim;
    int64_t inputShape[MAX_DIM];
    int64_t outputShape[MAX_DIM];
    int64_t inputStride[MAX_DIM];
    int64_t outputStride[MAX_DIM];
    int64_t dims[MAX_DIM];
};

extern "C" __global__ __aicore__ void permute(GM_ADDR x, GM_ADDR y,
                                              int64_t formerNum, int64_t formerLength,
                                              int64_t tailLength, int64_t tileLength,
                                              int64_t dtypeSize, int64_t ndim,
                                              GM_ADDR inputShape, GM_ADDR outputShape,
                                              GM_ADDR inputStride, GM_ADDR outputStride,
                                              GM_ADDR dims)
{
    if (dtypeSize == 2) {
        KernelPermute<half> op;
        op.Init(x, y, formerNum, formerLength, tailLength, tileLength,
                ndim, inputShape, outputShape, inputStride, outputStride, dims);
        op.Process();
    } else {
        KernelPermute<float> op;
        op.Init(x, y, formerNum, formerLength, tailLength, tileLength,
                ndim, inputShape, outputShape, inputStride, outputStride, dims);
        op.Process();
    }
}
