namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
constexpr int64_t MAX_DIM = 8;

at::Tensor permute(const at::Tensor &self, at::IntArrayRef dims)
{
    // ---- 输入校验 ----
    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kFloat || self.scalar_type() == at::kBFloat16,
                "permute: only float16, bfloat16 and float32 are supported, got ", self.scalar_type());

    int64_t ndim = self.dim();
    TORCH_CHECK(static_cast<int64_t>(dims.size()) == ndim,
                "permute: dims must have same length as input dimensions");

    // Compute output shape
    std::vector<int64_t> outputShapeVec(ndim);
    for (int64_t i = 0; i < ndim; ++i) {
        int64_t dim = dims[i];
        TORCH_CHECK(dim >= 0 && dim < ndim,
                    "permute: dim out of range");
        outputShapeVec[i] = self.size(dim);
    }

    at::Tensor output = at::empty(outputShapeVec, self.options());

    int64_t totalLength = self.numel();
    if (totalLength == 0) {
        return output;
    }

    int64_t dtypeSize = self.element_size();

    // ---- 预计算 stride ----
    std::vector<int64_t> inputShape(ndim);
    std::vector<int64_t> inputStride(ndim);
    std::vector<int64_t> outputStride(ndim);
    std::vector<int64_t> dimsVec(dims.begin(), dims.end());

    for (int64_t i = 0; i < ndim; ++i) {
        inputShape[i] = self.size(i);
    }

    // Compute input stride
    inputStride[ndim - 1] = 1;
    for (int64_t i = ndim - 2; i >= 0; --i) {
        inputStride[i] = inputStride[i + 1] * inputShape[i + 1];
    }

    // Compute output stride
    outputStride[ndim - 1] = 1;
    for (int64_t i = ndim - 2; i >= 0; --i) {
        outputStride[i] = outputStride[i + 1] * outputShapeVec[i + 1];
    }

    // ---- 获取硬件参数 ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block 级 tiling (核间切分, Cache Line 对齐) ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // ---- UB 级 tiling (核内切分) ----
    // Permute: single input, single output, data movement only
    // bufferCoefficient = inQueue(2*2) + outQueue(2*2) = 8 for fp16, 16 for fp32
    int64_t bufferCoefficient = dtypeSize * 8;
    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    if (dtypeSize == 0) { dtypeSize = 1; }
    int64_t alignElements = 32 / dtypeSize;
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength == 0) { tileLength = alignElements; }

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // Allocate device tensors for shape/stride/dims
    auto inputShapeTensor = at::empty({MAX_DIM}, at::TensorOptions().dtype(at::kLong).device(self.device()));
    auto outputShapeTensor = at::empty({MAX_DIM}, at::TensorOptions().dtype(at::kLong).device(self.device()));
    auto inputStrideTensor = at::empty({MAX_DIM}, at::TensorOptions().dtype(at::kLong).device(self.device()));
    auto outputStrideTensor = at::empty({MAX_DIM}, at::TensorOptions().dtype(at::kLong).device(self.device()));
    auto dimsTensor = at::empty({MAX_DIM}, at::TensorOptions().dtype(at::kLong).device(self.device()));

    // Copy data to device tensors
    auto inputShapeHost = inputShapeTensor.cpu();
    auto outputShapeHost = outputShapeTensor.cpu();
    auto inputStrideHost = inputStrideTensor.cpu();
    auto outputStrideHost = outputStrideTensor.cpu();
    auto dimsHost = dimsTensor.cpu();

    int64_t *inputShapePtr = inputShapeHost.data_ptr<int64_t>();
    int64_t *outputShapePtr = outputShapeHost.data_ptr<int64_t>();
    int64_t *inputStridePtr = inputStrideHost.data_ptr<int64_t>();
    int64_t *outputStridePtr = outputStrideHost.data_ptr<int64_t>();
    int64_t *dimsPtr = dimsHost.data_ptr<int64_t>();

    for (int64_t i = 0; i < ndim; ++i) {
        inputShapePtr[i] = inputShape[i];
        outputShapePtr[i] = outputShapeVec[i];
        inputStridePtr[i] = inputStride[i];
        outputStridePtr[i] = outputStride[i];
        dimsPtr[i] = dimsVec[i];
    }
    for (int64_t i = ndim; i < MAX_DIM; ++i) {
        inputShapePtr[i] = 0;
        outputShapePtr[i] = 0;
        inputStridePtr[i] = 0;
        outputStridePtr[i] = 0;
        dimsPtr[i] = 0;
    }

    inputShapeTensor.copy_(inputShapeHost);
    outputShapeTensor.copy_(outputShapeHost);
    inputStrideTensor.copy_(inputStrideHost);
    outputStrideTensor.copy_(outputStrideHost);
    dimsTensor.copy_(dimsHost);

    int64_t ndimVal = ndim;

    EXEC_KERNEL_CMD(permute, blockDim,
                    self, output,
                    formerNum, formerLength, tailLength, tileLength, dtypeSize, ndimVal,
                    inputShapeTensor, outputShapeTensor,
                    inputStrideTensor, outputStrideTensor,
                    dimsTensor);

    return output;
}

}  // namespace ascend_kernel
