14	constexpr int32_t BUFFER_NUM = 2;
15	constexpr int32_t MAX_DIM = 8;
16	
17	template <typename T>
18	class KernelPermute {
19	public:
20	    __aicore__ inline KernelPermute() {}
21	
22	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
23	                                int64_t formerNum, int64_t formerLength,
24	                                int64_t tailLength, int64_t tileLength,
25	                                int64_t ndim,
26	                                GM_ADDR inputShape, GM_ADDR outputShape,
27	                                GM_ADDR inputStride, GM_ADDR outputStride,
28	                                GM_ADDR dims)
29	    {
30	        int64_t blockIdx = AscendC::GetBlockIdx();
31	
32	        if (blockIdx < formerNum) {
33	            this->blockLength = formerLength;
34	            int64_t offset = formerLength * blockIdx;
35	            xGm.SetGlobalBuffer((__gm__ T *)x, offset + formerLength);
36	            yGm.SetGlobalBuffer((__gm__ T *)y, offset + formerLength);
37	            this->blockOffset = offset;
38	        } else {
39	            this->blockLength = tailLength;
40	            int64_t tailIdx = blockIdx - formerNum;
41	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
42	            xGm.SetGlobalBuffer((__gm__ T *)x, offset + tailLength);
43	            yGm.SetGlobalBuffer((__gm__ T *)y, offset + tailLength);
44	            this->blockOffset = offset;
45	        }
46	
47	        this->tileLength = tileLength;
48	        this->ndim = ndim;
49	
50	        // Read shape/stride/dims from GM
51	        auto shapeGm = (__gm__ int64_t *)inputShape;
52	        auto outShapeGm = (__gm__ int64_t *)outputShape;
53	        auto strideGm = (__gm__ int64_t *)inputStride;
54	        auto outStrideGm = (__gm__ int64_t *)outputStride;
55	        auto dimsGm = (__gm__ int64_t *)dims;
56	
57	        for (int64_t i = 0; i < ndim && i < MAX_DIM; ++i) {
58	            this->inputShape[i] = shapeGm[i];
59	            this->outputShape[i] = outShapeGm[i];
60	            this->inputStride[i] = strideGm[i];
61	            this->outputStride[i] = outStrideGm[i];
62	            this->dims[i] = dimsGm[i];
63	        }
64	
65	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
66	        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
67	    }
68	
69	    __aicore__ inline void Process()
70	    {
71	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
72	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
73	
74	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
75	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
76	
77	        for (int64_t i = 0; i < tileNum - 1; ++i) {
78	            CopyIn(i, this->tileLength);
79	            Compute(i, this->tileLength);
80	            CopyOut(i, this->tileLength);
81	        }
82	        if (tileNum > 0) {
83	            CopyIn(tileNum - 1, alignedTailLen);
84	            Compute(tileNum - 1, alignedTailLen);
85	            CopyOut(tileNum - 1, alignedTailLen);
86	        }
87	    }
88	
89	private:
90	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
91	    {
92	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
93	        // For permute, we don't actually copy data here - we compute indices in Compute
94	        // But we need to allocate the buffer for the pipeline
95	        inQueueX.EnQue(xLocal);
96	    }
97	
98	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
99	    {
100	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
101	        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
102	
103	        int64_t outGlobalOffset = this->blockOffset + progress * this->tileLength;
104	
105	        // For each element in the tile, compute the output index and map to input index
106	        for (int64_t i = 0; i < curTileLength; ++i) {
107	            int64_t outIdx = outGlobalOffset + i;
108	
109	            // Convert output linear index to output coordinates
110	            int64_t outCoords[MAX_DIM];
111	            int64_t tmp = outIdx;
112	            for (int64_t d = this->ndim - 1; d >= 0; --d) {
113	                outCoords[d] = tmp % this->outputShape[d];
114	                tmp /= this->outputShape[d];
115	            }
116	
117	            // Map output coordinates to input coordinates using dims
118	            int64_t inCoords[MAX_DIM];
119	            for (int64_t d = 0; d < this->ndim; ++d) {
120	                inCoords[this->dims[d]] = outCoords[d];
121	            }
122	
123	            // Compute input linear index
124	            int64_t inIdx = 0;
125	            for (int64_t d = 0; d < this->ndim; ++d) {
126	                inIdx += inCoords[d] * this->inputStride[d];
127	            }
128	
129	            // Copy element from input to output
130	            yLocal.SetValue(i, xGm.GetValue(inIdx));
131	        }
132	
133	        outQueueY.EnQue<T>(yLocal);
134	        inQueueX.FreeTensor(xLocal);
135	    }
136	
137	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
138	    {
139	        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
140	        int64_t globalOffset = this->blockOffset + progress * this->tileLength;
141	
142	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
143	        AscendC::DataCopyPad(yGm[globalOffset], yLocal, copyParams);
144	        outQueueY.FreeTensor(yLocal);
145	    }
146	
147	private:
148	    AscendC::TPipe pipe;
149	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
150	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
151	    AscendC::GlobalTensor<T> xGm;
152	    AscendC::GlobalTensor<T> yGm;
153	    int64_t blockLength;
154	    int64_t tileLength;
155	    int64_t blockOffset;
156	    int64_t ndim;
157	    int64_t inputShape[MAX_DIM];
158	    int64_t outputShape[MAX_DIM];
159	    int64_t inputStride[MAX_DIM];
160	    int64_t outputStride[MAX_DIM];
161	    int64_t dims[MAX_DIM];
162	};
163	
164	extern "C" __global__ __aicore__ void permute(GM_ADDR x, GM_ADDR y,
165	                                              int64_t formerNum, int64_t formerLength,
166	                                              int64_t tailLength, int64_t tileLength,
167	                                              int64_t dtypeSize, int64_t ndim,
168	                                              GM_ADDR inputShape, GM_ADDR outputShape,
169	                                              GM_ADDR inputStride, GM_ADDR outputStride,
170	                                              GM_ADDR dims)
171	{
172	    if (dtypeSize == 2) {
173	        KernelPermute<half> op;
174	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength,
175	                ndim, inputShape, outputShape, inputStride, outputStride, dims);
176	        op.Process();
177	    } else {
178	        KernelPermute<float> op;
179	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength,
180	                ndim, inputShape, outputShape, inputStride, outputStride, dims);
181	        op.Process();
182	    }
183	}
