22	template <int INPUT_COUNT>
23	class ConcatDim0KernelCommon {
24	public:
25	    __aicore__ inline void Init(
26	        GM_ADDR x0,
27	        GM_ADDR x1,
28	        GM_ADDR x2,
29	        GM_ADDR x3,
30	        GM_ADDR y,
31	        GM_ADDR tilingGM,
32	        AscendC::TPipe *pipe)
33	    {
34	        CopyTiling(&tiling_, tilingGM);
