36	        if constexpr (INPUT_COUNT >= 2) {
37	            x1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(x1), tiling_.M1 * tiling_.N);
38	        }
39	        if constexpr (INPUT_COUNT >= 3) {
40	            x2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(x2), tiling_.M2 * tiling_.N);
41	        }
42	        if constexpr (INPUT_COUNT >= 4) {
43	            x3GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(x3), tiling_.M3 * tiling_.N);
44	        }
45	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(y), tiling_.totalM * tiling_.N);
46	
47	        if ASCEND_IS_AIV {
48	            pipe_ = pipe;
49	            subBlockRows_ = tiling_.blockM / AscendC::GetSubBlockNum();
50	            pipe_->InitBuffer(xInQueue_, 1, AlignedRowBytes());
51	            pipe_->InitBuffer(yOutQueue_, 1, AlignedRowBytes());
52	        }
53	    }
54	
55	    __aicore__ inline void Process()
56	    {
57	        if ASCEND_IS_AIV {
58	            const int32_t coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
59	            const int32_t subBlockIdx = AscendC::GetSubBlockIdx();
60	            for (int32_t localIdx = 0; localIdx < tiling_.tasksPerCore; ++localIdx) {
61	                const int32_t bx = coreIdx * tiling_.tasksPerCore + localIdx;
62	                if (bx >= tiling_.blockNum) {
63	                    continue;
64	                }
65	                const int32_t rowBase = bx * tiling_.blockM + subBlockIdx * subBlockRows_;
66	                for (int32_t row = 0; row < subBlockRows_; ++row) {
67	                    const int32_t rowIdx = rowBase + row;
68	                    if (rowIdx < tiling_.totalM) {
69	                        ProcessRow(rowIdx);
70	                    }
71	                }
72	            }
73	        }
74	    }
75	
76	private:
77	    __aicore__ inline uint32_t RowBytes() const
78	    {
79	        return static_cast<uint32_t>(tiling_.N * static_cast<int32_t>(sizeof(float)));
80	    }
81	
82	    __aicore__ inline uint32_t AlignedRowBytes() const
83	    {
84	        const uint32_t rowBytes = RowBytes();
85	        return ((rowBytes + 31U) / 32U) * 32U;
86	    }
87	
88	    __aicore__ inline void CopyGmToUbRow(AscendC::LocalTensor<float> &dst, AscendC::GlobalTensor<float> src)
89	    {
90	        const uint32_t padElems = (AlignedRowBytes() - RowBytes()) / sizeof(float);
91	        AscendC::DataCopyExtParams copyParams{1, RowBytes(), 0, 0, 0};
92	        AscendC::DataCopyPadExtParams<float> padParams{true, 0, static_cast<uint8_t>(padElems), 0.0f};
93	        AscendC::DataCopyPad(dst, src, copyParams, padParams);
94	    }
95	
96	    __aicore__ inline void CopyUbToGmRow(AscendC::GlobalTensor<float> dst, AscendC::LocalTensor<float> &src)
97	    {
98	        AscendC::DataCopyExtParams copyParams{1, RowBytes(), 0, 0, 0};
99	        AscendC::DataCopyPad(dst, src, copyParams);
100	    }
101	
102	    __aicore__ inline void CopyInputRow(int32_t rowIdx, AscendC::LocalTensor<float> &dst)
103	    {
104	        if constexpr (INPUT_COUNT == 1) {
105	            CopyGmToUbRow(dst, x0GM_[rowIdx * tiling_.N]);
106	            return;
107	        }
108	
109	        if (rowIdx < tiling_.M0) {
110	            CopyGmToUbRow(dst, x0GM_[rowIdx * tiling_.N]);
111	            return;
112	        }
113	
114	        if constexpr (INPUT_COUNT >= 2) {
115	            const int32_t prefix01 = tiling_.M0 + tiling_.M1;
116	            if (rowIdx < prefix01) {
117	                CopyGmToUbRow(dst, x1GM_[(rowIdx - tiling_.M0) * tiling_.N]);
118	                return;
119	            }
120	
121	            if constexpr (INPUT_COUNT >= 3) {
122	                const int32_t prefix012 = prefix01 + tiling_.M2;
123	                if (rowIdx < prefix012) {
124	                    CopyGmToUbRow(dst, x2GM_[(rowIdx - prefix01) * tiling_.N]);
125	                    return;
126	                }
127	
128	                if constexpr (INPUT_COUNT >= 4) {
129	                    CopyGmToUbRow(dst, x3GM_[(rowIdx - prefix012) * tiling_.N]);
130	                    return;
131	                }
132	            }
133	        }
134	    }
135	
136	    __aicore__ inline void ProcessRow(int32_t rowIdx)
137	    {
138	        xInQueue_.AllocTensor<float>(xLocal_);
139	        yOutQueue_.AllocTensor<float>(yLocal_);
140	        CopyInputRow(rowIdx, xLocal_);
141	        xInQueue_.EnQue(xLocal_);
142	
143	        xInQueue_.DeQue<float>(xLocal_);
144	        AscendC::Adds(yLocal_, xLocal_, 0.0f, tiling_.N);
145	        xInQueue_.FreeTensor(xLocal_);
146	        yOutQueue_.EnQue(yLocal_);
147	
148	        yOutQueue_.DeQue<float>(yLocal_);
149	        CopyUbToGmRow(yGM_[rowIdx * tiling_.N], yLocal_);
150	        yOutQueue_.FreeTensor(yLocal_);
151	    }
152	
153	private:
154	    ConcatDim0Tiling tiling_{};
155	    AscendC::TPipe *pipe_{nullptr};
156	    int32_t subBlockRows_{0};
